}

:root[data-sc-surface] * {
  scrollbar-color: var(--sc-scrollbar-thumb) transparent;
}

:root[data-sc-surface] *::-webkit-scrollbar-thumb {
  background: var(--sc-scrollbar-thumb);
  border-radius: 1px;
}

/* =========================================================
 * 10. 脚本增强（需要 theme-rlyeh-archive.js）
 * ======================================================= */

.rl-fog,
.rl-tendrils,
.rl-eye,
.rl-sanity,
.rl-whisper {
  pointer-events: none;
  user-select: none;
}

.rl-fog[hidden],
.rl-tendrils[hidden],
.rl-eye[hidden],
.rl-sanity[hidden] {
  display: none !important;
}

/* 雾气与触须位于应用层之后，从透明的消息区透出来 */
:root[data-sc-theme='rlyeh-archive'] #app {
  position: relative;
  z-index: 1;
}

/* 深海雾气 */
.rl-fog {
  position: fixed;
  inset: -20%;
  z-index: 0;
  opacity: var(--rl-fog-opacity, 0.5);
  background:
    radial-gradient(ellipse 30% 18% at 20% 80%, rgba(120, 170, 160, 0.09), transparent 70%),
    radial-gradient(ellipse 26% 16% at 70% 88%, rgba(120, 170, 160, 0.08), transparent 70%),
    radial-gradient(ellipse 34% 20% at 45% 95%, rgba(140, 180, 170, 0.07), transparent 70%);
  animation: rl-drift 46s ease-in-out infinite alternate;
}

.rl-fog--slow {
  animation-duration: 71s;
  animation-direction: alternate-reverse;
  transform: scaleX(-1);
}

:root[data-sc-palette='day'] .rl-fog {
  opacity: 0.35;
  filter: sepia(1) saturate(0.6) brightness(0.7);
}

@keyframes rl-drift {
  from { translate: -6% 0; }
  to { translate: 6% -3%; }
}

/* 角落触须 */
.rl-tendrils {
  position: fixed;
  bottom: -10px;
  z-index: 0;
  width: clamp(120px, 16vw, 220px);
  height: clamp(200px, 34vh, 360px);
  opacity: 0.55;
}

.rl-tendrils--left { left: -26px; }
.rl-tendrils--right { right: -26px; transform: scaleX(-1); }

.rl-tendrils path {
  fill: color-mix(in srgb, var(--rl-abyss) 70%, #0f2e2a);
  transform-box: fill-box;
  transform-origin: 50% 100%;
  animation: rl-sway var(--rl-sway, 9s) ease-in-out infinite alternate;
  animation-delay: var(--rl-delay, 0s);
}

:root[data-sc-palette='day'] .rl-tendrils {
  opacity: 0.22;
}

:root[data-sc-palette='day'] .rl-tendrils path {
  fill: #3b2a17;
}

@keyframes rl-sway {
  from { rotate: -4deg; }
  to { rotate: 5deg; }
}

/* 注视之眼 */
.rl-eye {
  position: fixed;
  right: clamp(18px, 3vw, 46px);
  bottom: clamp(150px, 22vh, 220px);
  z-index: 4;
  width: 46px;
  height: 22px;
  opacity: 0;
  transition: opacity 2.4s ease;
}

.rl-eye.is-open {
  opacity: 0.6;
}

.rl-eye__lid {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 50%, #d8d2a8 0%, #8d8a62 60%, #3a3a26 100%);
  box-shadow: 0 0 18px var(--rl-eldritch-glow), inset 0 0 6px rgba(0, 0, 0, 0.6);
  transform: scaleY(0.08);
  transition: transform 0.9s cubic-bezier(0.3, 0.7, 0.2, 1);
}

.rl-eye.is-open .rl-eye__lid {
  transform: scaleY(1);
}

.rl-eye__pupil {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 5px;
  height: 18px;
  margin: -9px 0 0 -2.5px;
  border-radius: 50%;
  background: #050505;
  box-shadow: 0 0 0 4px rgba(120, 30, 20, 0.55);
  translate: var(--rl-look-x, 0) var(--rl-look-y, 0);
  transition: translate 0.4s ease;
}

:root[data-sc-palette='day'] .rl-eye.is-open {
  opacity: 0.35;
}

/* 理智值仪表 */
.rl-sanity {
  position: fixed;
  top: 0;
  left: 50%;
  z-index: 2000;
  height: 3.5rem;
  display: flex;
  align-items: center;
  gap: 10px;
  transform: translateX(-50%);
  font: 12px/1 var(--rl-type);
  letter-spacing: 0.12em;
  color: var(--sc-text-secondary);
  white-space: nowrap;
}

.rl-sanity__label b {
  color: var(--rl-brass);
  font-weight: 700;
}

.rl-sanity__bar {
  position: relative;
  width: 120px;
  height: 7px;
  border: 1px solid var(--sc-border-strong);
  background: repeating-linear-gradient(90deg, transparent 0 11px, var(--rl-rule) 11px 12px);
}

.rl-sanity__fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--rl-san-pct, 100%);
  background: linear-gradient(90deg, var(--rl-blood), var(--rl-brass) 60%, var(--rl-eldritch));
  background-size: 120px 100%;
  transition: width 1.2s ease;
}

.rl-sanity__value {
  min-width: 2.2ch;
  text-align: right;
  color: var(--sc-text-primary);
}

.rl-sanity.is-hit {
  animation: rl-hit 0.8s ease;
}

@keyframes rl-hit {
  0%, 100% { translate: 0; }
  20% { translate: -3px 0; color: var(--rl-blood); }
  40% { translate: 3px 0; }
  60% { translate: -2px 0; }
}

/* 低语 */
.rl-whisper {
  position: fixed;
  z-index: 5;
  max-width: 40vw;
  font: italic 15px/1.4 var(--rl-serif);
  letter-spacing: 0.24em;
  color: var(--rl-eldritch);
  text-shadow: 0 0 12px var(--rl-eldritch-glow);
  opacity: 0;
  animation: rl-whisper 7s ease-in-out forwards;
}

@keyframes rl-whisper {
  0% { opacity: 0; filter: blur(6px); }
  30% { opacity: 0.55; filter: blur(0.4px); }
  70% { opacity: 0.4; filter: blur(1px); }
  100% { opacity: 0; filter: blur(8px); translate: 0 -14px; }
}

/* 禁忌词：文字像在纸面上缓慢蠕动 */
[data-sc-ui='message'][data-rl-eldritch] .chat-item > .right > .content {
  animation: rl-squirm 5s ease-in-out infinite;
}

[data-sc-ui='message-list'].chat--layout-compact [data-sc-ui='message'][data-rl-eldritch] .message-row__surface,
[data-sc-ui='message'][data-rl-eldritch] .chat-item--layout-bubble > .right > .content {
  box-shadow: inset 3px 0 0 var(--rl-eldritch), inset 40px 0 40px -30px var(--rl-eldritch-glow);
}

@keyframes rl-squirm {
  0%, 100% { text-shadow: 0 0 0 transparent; letter-spacing: 0.02em; }
  50% { text-shadow: 1px 0 4px var(--rl-eldritch-glow), -1px 0 2px rgba(176, 42, 42, 0.25); letter-spacing: 0.045em; }
}

/* d100 大成功 / 大失败 */
[data-sc-ui='message'][data-rl-roll]::after {
  position: absolute;
  right: 3.2rem;
  top: 50%;
  z-index: 2;
  padding: 2px 10px;
  font: 700 14px/1.3 var(--rl-serif);
  letter-spacing: 0.3em;
  border: 2px solid currentColor;
  border-radius: 3px;
  transform: translateY(-50%) rotate(-10deg);
  pointer-events: none;
  opacity: 0.85;
}

[data-sc-ui='message'][data-rl-roll='fumble']::after {
  content: "大失败";
  color: var(--rl-blood);
  background: radial-gradient(circle at 30% 40%, color-mix(in srgb, var(--rl-blood) 30%, transparent), transparent 60%);
}

[data-sc-ui='message'][data-rl-roll='crit']::after {
  content: "大成功";
  color: var(--rl-brass);
}

[data-sc-ui='message'][data-rl-roll='fumble'] .message-row__surface {
  background-image: radial-gradient(circle at 92% 40%, color-mix(in srgb, var(--rl-blood) 18%, transparent), transparent 22%) !important;
}

/* 理智阶段：越低越暗，边缘轻微晃动 */
:root[data-rl-madness='1'] { --rl-vignette: 0.6; --rl-vignette-day: 0.28; --rl-fog-opacity: 0.7; }
:root[data-rl-madness='2'] { --rl-vignette: 0.75; --rl-vignette-day: 0.38; --rl-fog-opacity: 0.85; }
:root[data-rl-madness='3'] { --rl-vignette: 0.88; --rl-vignette-day: 0.5; --rl-fog-opacity: 1; }

:root[data-rl-madness='3'] [data-sc-ui='message-list'] {
  animation: rl-unease 9s ease-in-out infinite;
}

@keyframes rl-unease {
  0%, 100% { filter: none; }
  50% { filter: hue-rotate(-12deg) saturate(1.15); }
}

/* =========================================================
 * 11. 紧凑布局 / 窄屏 / 减少动画
 * ======================================================= */

:root[data-sc-layout='compact'] [data-sc-ui='message'] .chat-item--ic > .right > .content {
  line-height: 1.7;
}

@media (max-width: 960px) {
  .rl-sanity { display: none !important; }
}

@media (max-width: 640px) {
  [data-sc-ui='header'] .sc-channel-title::before { display: none; }
  [data-sc-ui='channel-list'] .sider-item.active::after { display: none; }
  .rl-tendrils, .rl-eye { display: none !important; }

  [data-sc-ui='message'] .chat-item__avatar .avatar-shell {
    border-width: 2px;
    border-bottom-width: 4px;
  }

  [data-sc-ui='message'][data-rl-roll]::after {
    right: 0.6rem;
    font-size: 11px;
  }

  :root[data-sc-surface='auth'] .sign-in-content::after { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph),
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph)::before,
  :root[data-sc-surface] *:not(.tiptap-performance):not(.twin-layer-message__char):not(.twin-layer-message__char-glyph)::after {
    scroll-behavior: auto !important;
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }

  .rl-fog, .rl-whisper { display: none; }
}

js:
// R'LYEH ARCHIVE 拉莱耶档案馆 —— 配套脚本（纯装饰）
// 只添加 aria-hidden 的装饰层，并给消息行写入 data-rl-* 标记；
// 不移动、不改写 SealChat 的 DOM 文本，不发网络请求。
// 「理智值」只是本标签页内的氛围效果，保存在 sessionStorage，与游戏数据无关。

const doc = document
const root = doc.documentElement
const THEME = 'rlyeh-archive'
const SVG_NS = 'http://www.w3.org/2000/svg'
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
const QUIET_SURFACES = new Set(['embed', 'log-public', 'theater'])
const SANITY_SURFACES = new Set(['chat', 'split'])
const SAN_KEY = 'sealchat.theme.rlyeh-archive.san'
const SAN_MAX = 99

const ELDRITCH = /克苏鲁|cthulhu|拉莱耶|r'?lyeh|ph'?nglui|fhtagn|古神|旧日支配者|外神|深潜者|触手|奈亚拉托提普|nyarlathotep|阿撒托斯|azathoth|犹格|yog-?sothoth|死灵之书|necronomicon|不可名状|疯狂/i
const D100 = /d100\s*[=:：]\s*(\d{1,3})/i
const WHISPERS = [
  "Ph'nglui mglw'nafh Cthulhu R'lyeh wgah'nagl fhtagn",
  '它在沉没之城中做梦',
  '不要回头看书架的阴影',
  '那不是潮声',
  '门后的东西记住了你的名字',
  '星辰的位置……快要正确了',
  'Iä! Iä!',
  '你确定刚才那句话是你写的吗？',
]

root.dataset.scTheme = THEME
sc.cleanup(() => {
  if (root.dataset.scTheme === THEME) delete root.dataset.scTheme
  delete root.dataset.rlMadness
})

const make = (tag, className, parent = doc.body) => {
  const el = doc.createElement(tag)
  el.className = className
  el.setAttribute('aria-hidden', 'true')
  parent.appendChild(el)
  sc.cleanup(() => el.remove())
  return el
}
const rand = (min, max) => min + Math.random() * (max - min)

/* ---------- 雾气与触须 ---------- */

const fogs = reduceMotion ? [] : [make('div', 'rl-fog'), make('div', 'rl-fog rl-fog--slow')]

// 以中心线加锥形宽度生成一条触须轮廓
const tentaclePath = (baseX, height, bend, width, curl) => {
  const steps = 28
  const centre = []
  for (let i = 0; i <= steps; i += 1) {
    const t = i / steps
    const x = baseX + Math.sin(t * Math.PI * 1.25) * bend * t + curl * t * t * t
    const y = 400 - t * height - Math.max(0, t - 0.85) * curl * 0.6
    centre.push([x, y, (1 - t) * (width / 2) + 0.8])
  }
  const left = []
  const right = []
  centre.forEach(([x, y, w], i) => {
    const [ax, ay] = centre[Math.max(0, i - 1)]
    const [bx, by] = centre[Math.min(steps, i + 1)]
    const len = Math.hypot(bx - ax, by - ay) || 1
    const nx = -(by - ay) / len
    const ny = (bx - ax) / len
    left.push(`${(x + nx * w).toFixed(1)} ${(y + ny * w).toFixed(1)}`)
    right.unshift(`${(x - nx * w).toFixed(1)} ${(y - ny * w).toFixed(1)}`)
  })
  return `M${left.join(' L')} L${right.join(' L')} Z`
}

const buildTendrils = side => {
  const svg = doc.createElementNS(SVG_NS, 'svg')
  svg.setAttribute('class', `rl-tendrils rl-tendrils--${side}`)
  svg.setAttribute('viewBox', '0 0 200 400')
  svg.setAttribute('preserveAspectRatio', 'xMidYMax meet')
  svg.setAttribute('aria-hidden', 'true')
  const specs = [
    [44, 330, 38, 34, 26, 11, 0],
    [92, 250, -30, 26, -22, 8.5, -2.5],
    [20, 190, 22, 20, 18, 13, -5],
  ]
  for (const [x, h, bend, w, curl, sway, delay] of specs) {
    const path = doc.createElementNS(SVG_NS, 'path')
    path.setAttribute('d', tentaclePath(x, h, bend, w, curl))
    path.style.setProperty('--rl-sway', `${sway}s`)
    path.style.setProperty('--rl-delay', `${delay}s`)
    svg.appendChild(path)
  }
  doc.body.appendChild(svg)
  sc.cleanup(() => svg.remove())
  return svg
}
const tendrils = [buildTendrils('left'), buildTendrils('right')]

/* ---------- 注视之眼 ---------- */

const eye = make('div', 'rl-eye')
eye.innerHTML = '<div class="rl-eye__lid"><div class="rl-eye__pupil"></div></div>'
let pointerFrame = 0
sc.listen(window, 'pointermove', event => {
  if (!eye.classList.contains('is-open') || pointerFrame) return
  pointerFrame = window.requestAnimationFrame(() => {
    pointerFrame = 0
    const rect = eye.getBoundingClientRect()
    const dx = event.clientX - (rect.left + rect.width / 2)
    const dy = event.clientY - (rect.top + rect.height / 2)
    const dist = Math.hypot(dx, dy) || 1
    eye.style.setProperty('--rl-look-x', `${((dx / dist) * Math.min(12, dist / 30)).toFixed(1)}px`)
    eye.style.setProperty('--rl-look-y', `${((dy / dist) * Math.min(3, dist / 90)).toFixed(1)}px`)
  })
}, { passive: true })
sc.cleanup(() => { if (pointerFrame) window.cancelAnimationFrame(pointerFrame) })

const scheduleEye = () => {
  sc.timeout(() => {
    if (!doc.hidden && !eye.hidden) {
      eye.classList.add('is-open')
      sc.timeout(() => eye.classList.remove('is-open'), rand(5000, 9000))
    }
    scheduleEye()
  }, rand(22000, 55000))
}
if (!reduceMotion) scheduleEye()

/* ---------- 理智值 ---------- */

const sanity = make('div', 'rl-sanity')
sanity.innerHTML = '<span class="rl-sanity__label">理智 <b>SAN</b></span><span class="rl-sanity__bar"><span class="rl-sanity__fill"></span></span><span class="rl-sanity__value"></span>'
const sanityValue = sanity.querySelector('.rl-sanity__value')

const readSan = () => {
  try {
    const value = Number(window.sessionStorage.getItem(SAN_KEY))
    return Number.isFinite(value) && value > 0 ? Math.min(SAN_MAX, value) : SAN_MAX
  } catch { return SAN_MAX }
}
let san = readSan()

const renderSan = () => {
  sanityValue.textContent = String(san)
  sanity.style.setProperty('--rl-san-pct', `${Math.round((san / SAN_MAX) * 100)}%`)
  const level = san < 10 ? '3' : san < 30 ? '2' : san < 60 ? '1' : ''
  if (level) root.dataset.rlMadness = level
  else delete root.dataset.rlMadness
}

const setSan = (next, hit = false) => {
  san = Math.max(1, Math.min(SAN_MAX, Math.round(next)))
  try { window.sessionStorage.setItem(SAN_KEY, String(san)) } catch { /* 隐私模式 */ }
  renderSan()
  if (hit && !reduceMotion) {
    sanity.classList.remove('is-hit')
    void sanity.offsetWidth
    sanity.classList.add('is-hit')
  }
}
renderSan()
sc.interval(() => { if (san < SAN_MAX) setSan(san + 1) }, 90000)

/* ---------- 低语 ---------- */

const whisper = () => {
  const el = make('div', 'rl-whisper')
  el.textContent = WHISPERS[Math.floor(Math.random() * WHISPERS.length)]
  const leftSide = Math.random() < 0.5
  el.style.top = `${rand(18, 70).toFixed(0)}vh`
  el.style[leftSide ? 'left' : 'right'] = `${rand(3, 22).toFixed(0)}vw`
  sc.timeout(() => el.remove(), 7600)
}

const scheduleWhisper = () => {
  sc.timeout(() => {
    const surface = sc.context().surface
    if (!doc.hidden && (surface === 'chat' || surface === 'lobby' || surface === 'world-detail')) whisper()
    scheduleWhisper()
  }, rand(48000, 110000))
}
if (!reduceMotion) scheduleWhisper()

/* ---------- Surface 切换 ---------- */

const renderSurface = () => {
  const surface = sc.context().surface
  const quiet = QUIET_SURFACES.has(surface)
  for (const el of [...fogs, ...tendrils, eye]) el.hidden = quiet
  sanity.hidden = !SANITY_SURFACES.has(surface)
}
renderSurface()
sc.on('surface-change', renderSurface)

/* ---------- 消息标记：禁忌词与 d100 ---------- */

const rowText = row => {
  const content = row.querySelector('.content')
  return (content || row).textContent || ''
}

const markRow = row => {
  const text = rowText(row)
  const signature = String(text.length)
  if (row.dataset.rlSig === signature) return
  row.dataset.rlSig = signature
  if (ELDRITCH.test(text)) row.dataset.rlEldritch = '1'
  else delete row.dataset.rlEldritch
  const roll = D100.exec(text)
  const value = roll ? Number(roll[1]) : NaN
  if (value >= 96 && value <= 100) row.dataset.rlRoll = 'fumble'
  else if (value >= 1 && value <= 5) row.dataset.rlRoll = 'crit'
  else delete row.dataset.rlRoll
}

const scanRows = () => {
  for (const row of doc.querySelectorAll('[data-sc-ui="message"]')) markRow(row)
}

let scanQueued = false
const queueScan = () => {
  if (scanQueued) return
  scanQueued = true
  sc.timeout(() => { scanQueued = false; scanRows() }, 220)
}
scanRows()
sc.observe(doc.body, { childList: true, subtree: true }, queueScan)

sc.cleanup(() => {
  for (const row of doc.querySelectorAll('[data-rl-sig]')) {
    delete row.dataset.rlSig
    delete row.dataset.rlEldritch
    delete row.dataset.rlRoll
  }
})

sc.on('message-updated', queueScan)
sc.on('message-created', payload => {
  queueScan()
  const ctx = sc.context()
  if (!payload || !SANITY_SURFACES.has(ctx.surface)) return
  if (payload.channelId && payload.channelId !== ctx.channelId) return
  const text = String(payload.contentText || payload.contentRaw || '')
  let loss = 0
  if (ELDRITCH.test(text)) loss += Math.ceil(rand(0.01, 3))
  const roll = D100.exec(text)
  if (roll && Number(roll[1]) >= 96) loss += 1
  if (loss) setSan(san - loss, true)
})
